package com.circunet.controller;
import com.circunet.security.JwtService; import com.circunet.exception.ApiException; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {
 private final JdbcTemplate db; private final PasswordEncoder encoder; private final JwtService jwt;
 public AuthController(JdbcTemplate db,PasswordEncoder encoder,JwtService jwt){this.db=db;this.encoder=encoder;this.jwt=jwt;}
 public record Login(@Email @NotBlank String email,@NotBlank String password){} public record Register(Map<String,Object> company,List<Map<String,Object>> residues,List<Map<String,Object>> needs){}
 @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Register body){Map<String,Object> c=body.company(); if(c==null)throw ApiException.bad("company is required"); String role=Objects.toString(c.get("role"),""); if("ADMIN".equalsIgnoreCase(role))throw ApiException.forbidden(); String email=Objects.toString(c.get("email"),"").toLowerCase(); if(!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw ApiException.bad("Valid email required"); String password=Objects.toString(c.get("password"),"");if(password.length()<8)throw ApiException.bad("password must be at least 8 characters"); if((role.equals("SELLER")||role.equals("BOTH"))&&(body.residues()==null||body.residues().isEmpty()))throw ApiException.bad("residues required for seller");if((role.equals("BUYER")||role.equals("BOTH"))&&(body.needs()==null||body.needs().isEmpty()))throw ApiException.bad("needs required for buyer");
 db.update("INSERT INTO companies(name,contact_person,email,phone,password_hash,industry_type,role,state,city,address,lat,lng) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",c.get("name"),c.get("contactPerson"),email,c.get("phone"),encoder.encode(password),c.get("industryType"),role,c.get("state"),c.get("city"),c.get("address"),num(c.get("lat")),num(c.get("lng"))); long id=db.queryForObject("SELECT id FROM companies WHERE email=?",Long.class,email);saveChildren(id,body.residues(),body.needs()); return ResponseEntity.status(201).body(tokens(id,role)); }
 private void saveChildren(long id,List<Map<String,Object>> residues,List<Map<String,Object>> needs){if(residues!=null)for(var r:residues)db.update("INSERT INTO company_residues(company_id,material_id,custom_name,qty_per_month_tonnes,disposal_method,disposal_cost_per_tonne) VALUES(?,?,?,?,?,?)",id,r.get("materialId"),r.get("customName"),num(r.get("qtyPerMonthTonnes")),r.get("disposalMethod"),num(r.get("disposalCostPerTonne")));if(needs!=null)for(var n:needs)db.update("INSERT INTO company_needs(company_id,material_id,qty_per_month_tonnes,quality_notes) VALUES(?,?,?,?)",id,n.get("materialId"),num(n.get("qtyPerMonthTonnes")),n.get("qualityNotes"));}
 @PostMapping("/login") public Object login(@Valid @RequestBody Login in){String email=in.email().toLowerCase();List<Map<String,Object>> rows=db.queryForList("SELECT * FROM companies WHERE email=?",email);if(rows.isEmpty()||!encoder.matches(in.password(),Objects.toString(rows.isEmpty()?"":rows.get(0).get("password_hash"),"")))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");var c=rows.get(0);return tokens(((Number)c.get("id")).longValue(),Objects.toString(c.get("role")));}
 @PostMapping("/refresh") public Object refresh(@RequestBody Map<String,String> b){try{var claims=jwt.parse(b.get("refreshToken"));if(!"refresh".equals(claims.get("type")))throw new RuntimeException();return Map.of("accessToken",jwt.access(Long.parseLong(claims.getSubject()),Objects.toString(claims.get("role"))));}catch(Exception e){throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid refresh token");}}
 @PostMapping("/forgot-password") public ResponseEntity<?> forgot(@RequestBody Map<String,String> b){return ResponseEntity.accepted().body(Map.of("message","If the account exists, password reset instructions would be sent."));}
 @GetMapping("/me") public Object me(@org.springframework.security.core.annotation.AuthenticationPrincipal String id){return db.queryForMap("SELECT id,name,contact_person AS \"contactPerson\",email,phone,industry_type AS \"industryType\",role,state,city,address,lat,lng,created_at AS \"createdAt\" FROM companies WHERE id=?",Long.parseLong(id));}
 private Map<String,Object> tokens(long id,String role){return Map.of("accessToken",jwt.access(id,role),"refreshToken",jwt.refresh(id,role),"company",db.queryForMap("SELECT id,name,contact_person AS \"contactPerson\",email,phone,industry_type AS \"industryType\",role,state,city,address,lat,lng,created_at AS \"createdAt\" FROM companies WHERE id=?",id));}
 private Double num(Object o){return o==null||o.toString().isBlank()?null:Double.valueOf(o.toString());}
}
